        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>FOOTSTOOL</strong> connected with a throne (2 Chronicles 9:18). Jehovah symbolically dwelt in the holy place between the cherubim above the ark of the covenant. The ark was his footstool (1 Chronicles 28:2; Psalm 99:5; 132:7). And as heaven is God’s throne, so the earth is his footstool (Psalm 110:1; Isaiah 66:1; Matthew 5:35).",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
